def _validate24(value: object, path: str, errors: list[str]) -> None:
    start = len(errors)
    before = len(errors)
    _validate14(value, path, errors)
    if len(errors) == before:
        del errors[start:]
        return
    before = len(errors)
    _validate16(value, path, errors)
